CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY);
CREATE TABLE accounts (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL);
CREATE TABLE auth_sessions (token_hash text PRIMARY KEY, user_id uuid REFERENCES accounts(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE campaigns (id uuid PRIMARY KEY, name text NOT NULL, ruleset text NOT NULL DEFAULT '5e-2014', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (campaign_id uuid REFERENCES campaigns(id) ON DELETE CASCADE, user_id uuid REFERENCES accounts(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('DM','PLAYER')), PRIMARY KEY(campaign_id,user_id));
CREATE TABLE invitations (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), email text NOT NULL, token_hash text UNIQUE NOT NULL, accepted_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE characters (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), owner_id uuid REFERENCES accounts(id), name text NOT NULL, class_name text NOT NULL, revision integer NOT NULL DEFAULT 0, fields jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now(), UNIQUE(campaign_id,id));
CREATE TABLE resources (id uuid PRIMARY KEY, campaign_id uuid NOT NULL, character_id uuid NOT NULL, name text NOT NULL, balance integer NOT NULL CHECK(balance >= 0), revision integer NOT NULL DEFAULT 0, FOREIGN KEY(campaign_id,character_id) REFERENCES characters(campaign_id,id), UNIQUE(campaign_id,id));
CREATE TABLE sessions (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), title text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', synthetic boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,id));
CREATE TABLE recording_consents (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES accounts(id), granted boolean NOT NULL, notice text NOT NULL, created_at timestamptz DEFAULT now(), FOREIGN KEY(campaign_id,session_id) REFERENCES sessions(campaign_id,id));
CREATE TABLE evidence (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid, visibility text NOT NULL CHECK(visibility IN ('PARTY','DM')), speaker text NOT NULL, start_ms integer NOT NULL DEFAULT 0, end_ms integer NOT NULL DEFAULT 0, content text NOT NULL, source text NOT NULL, created_at timestamptz DEFAULT now(), FOREIGN KEY(campaign_id,session_id) REFERENCES sessions(campaign_id,id), UNIQUE(campaign_id,id));
CREATE TABLE documents (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), character_id uuid, submitted_by uuid REFERENCES accounts(id), storage_key text NOT NULL, sha256 text NOT NULL, mime text NOT NULL, extracted jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE facts (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid, kind text NOT NULL, visibility text NOT NULL CHECK(visibility IN ('PARTY','DM')), content text NOT NULL, revision integer NOT NULL DEFAULT 0, evidence_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz DEFAULT now(), UNIQUE(campaign_id,id));
CREATE TABLE proposals (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid, target_kind text NOT NULL CHECK(target_kind IN ('RESOURCE','FACT','IMPORT')), target_id uuid, submitted_by uuid REFERENCES accounts(id), submitted_by_type text NOT NULL CHECK(submitted_by_type IN ('AI','PLAYER','DM')), visibility text NOT NULL CHECK(visibility IN ('PARTY','DM')), patch jsonb NOT NULL, reason text NOT NULL, evidence_ids jsonb NOT NULL, base_revision integer NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'PENDING_DM', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,id));
CREATE TABLE decisions (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), proposal_id uuid NOT NULL, reviewer_id uuid NOT NULL REFERENCES accounts(id), state text NOT NULL, accepted_patch jsonb, public_reason text NOT NULL DEFAULT '', private_reason text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now(), FOREIGN KEY(campaign_id,proposal_id) REFERENCES proposals(campaign_id,id), UNIQUE(proposal_id));
CREATE TABLE ledger_entries (id uuid PRIMARY KEY, campaign_id uuid NOT NULL, resource_id uuid NOT NULL, proposal_id uuid NOT NULL, delta integer NOT NULL, before_balance integer NOT NULL, after_balance integer NOT NULL CHECK(after_balance >= 0), reviewer_id uuid NOT NULL REFERENCES accounts(id), reason text NOT NULL, evidence_ids jsonb NOT NULL, compensates_id uuid REFERENCES ledger_entries(id), idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(campaign_id,resource_id) REFERENCES resources(campaign_id,id), FOREIGN KEY(campaign_id,proposal_id) REFERENCES proposals(campaign_id,id));
CREATE TABLE reports (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid, revision integer NOT NULL, visibility text NOT NULL CHECK(visibility IN ('PARTY','DM')), body jsonb NOT NULL, published boolean NOT NULL DEFAULT false, amended boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,session_id,revision,visibility));
CREATE TABLE async_jobs (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), session_id uuid NOT NULL, type text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, error text, idempotency_key text UNIQUE NOT NULL, created_at timestamptz DEFAULT now(), FOREIGN KEY(campaign_id,session_id) REFERENCES sessions(campaign_id,id));
CREATE TABLE audit_logs (id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns(id), user_id uuid REFERENCES accounts(id), kind text NOT NULL, subject_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX evidence_timeline ON evidence(campaign_id,session_id,start_ms);
CREATE INDEX proposals_queue ON proposals(campaign_id,state,created_at);
CREATE INDEX ledger_history ON ledger_entries(campaign_id,created_at);
CREATE INDEX evidence_search ON evidence USING gin(to_tsvector('english',content));
CREATE FUNCTION aar_role(cid uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM memberships WHERE campaign_id=cid AND user_id=nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE ROLE aar_app NOLOGIN;
GRANT USAGE ON SCHEMA public TO aar_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO aar_app;
REVOKE ALL ON accounts, auth_sessions, schema_migrations FROM aar_app;
ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_access ON campaigns USING(aar_role(id) IS NOT NULL);
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_access ON memberships USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE characters ENABLE ROW LEVEL SECURITY;
CREATE POLICY characters_access ON characters USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY resources_access ON resources USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sessions_access ON sessions USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE recording_consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY recording_consents_access ON recording_consents USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_access ON evidence USING(aar_role(campaign_id) IS NOT NULL AND (visibility='PARTY' OR aar_role(campaign_id)='DM'));
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_access ON documents USING(aar_role(campaign_id) IS NOT NULL AND aar_role(campaign_id)='DM');
ALTER TABLE facts ENABLE ROW LEVEL SECURITY;
CREATE POLICY facts_access ON facts USING(aar_role(campaign_id) IS NOT NULL AND (visibility='PARTY' OR aar_role(campaign_id)='DM'));
ALTER TABLE proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY proposals_access ON proposals USING(aar_role(campaign_id) IS NOT NULL AND (visibility='PARTY' OR aar_role(campaign_id)='DM'));
ALTER TABLE decisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY decisions_access ON decisions USING(aar_role(campaign_id) IS NOT NULL AND aar_role(campaign_id)='DM');
ALTER TABLE ledger_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY ledger_entries_access ON ledger_entries USING(aar_role(campaign_id) IS NOT NULL);
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_access ON reports USING(aar_role(campaign_id) IS NOT NULL AND (visibility='PARTY' OR aar_role(campaign_id)='DM') AND (published OR aar_role(campaign_id)='DM'));
ALTER TABLE async_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY async_jobs_access ON async_jobs USING(aar_role(campaign_id) IS NOT NULL AND aar_role(campaign_id)='DM');
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_logs_access ON audit_logs USING(aar_role(campaign_id) IS NOT NULL AND aar_role(campaign_id)='DM');
ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitations_access ON invitations USING(aar_role(campaign_id) IS NOT NULL AND aar_role(campaign_id)='DM');
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable history'; END $$;
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON evidence FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_ledger_entries BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_decisions BEFORE UPDATE OR DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_audit_logs BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_recording_consents BEFORE UPDATE OR DELETE ON recording_consents FOR EACH ROW EXECUTE FUNCTION immutable_row();
